CREATE DATABASE IF NOT EXISTS app_store CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE app_store;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE apps(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(100) NOT NULL,short_description VARCHAR(255) DEFAULT '',description TEXT NOT NULL,download_url VARCHAR(2048),status ENUM('draft','published') DEFAULT 'draft',created_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status,category)) ENGINE=InnoDB;
CREATE TABLE screenshots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,app_id BIGINT UNSIGNED NOT NULL,filename VARCHAR(255) NOT NULL,caption VARCHAR(255) DEFAULT '',FOREIGN KEY(app_id) REFERENCES apps(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE services(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,category VARCHAR(100) DEFAULT 'Dịch vụ mạng',description TEXT NOT NULL,price DECIMAL(14,2) DEFAULT 0,duration VARCHAR(100) DEFAULT '30 ngày',contact_url VARCHAR(2048),status ENUM('active','hidden') DEFAULT 'hidden',sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;